import pyomo.environ as pyo

DATA = {
    "centers": [1, 2, 3, 4, 5],
    "stores": [1, 2, 3, 4, 5, 6, 7, 8, 9],
    "opening_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000, 5: 160000,
    },
    "capacity": {
        1: 1825, 2: 1821, 3: 1365, 4: 1929, 5: 1502,
    },
    "demand": {
        1: 739, 2: 491, 3: 766, 4: 854, 5: 827,
        6: 908, 7: 434, 8: 605, 9: 480,
    },
    "transport_cost": {
        1: {1: 5, 2: 2, 3: 3, 4: 3, 5: 3, 6: 5, 7: 4, 8: 3, 9: 5},
        2: {1: 2, 2: 4, 3: 2, 4: 4, 5: 5, 6: 1, 7: 4, 8: 2, 9: 5},
        3: {1: 4, 2: 1, 3: 1, 4: 3, 5: 3, 6: 2, 7: 4, 8: 4, 9: 3},
        4: {1: 4, 2: 4, 3: 1, 4: 3, 5: 5, 6: 3, 7: 5, 8: 1, 9: 2},
        5: {1: 4, 2: 1, 3: 4, 4: 2, 5: 2, 6: 1, 7: 2, 8: 5, 9: 2},
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["centers"])
    model.J = pyo.Set(initialize=d["stores"])

    # Decision variables
    model.open = pyo.Var(model.I, within=pyo.Binary)
    model.ship = pyo.Var(model.I, model.J, within=pyo.NonNegativeReals)

    # Objective: minimize opening + transportation cost
    def obj_rule(m):
        opening = sum(d["opening_cost"][i] * m.open[i] for i in m.I)
        transport = sum(d["transport_cost"][i][j] * m.ship[i, j]
                        for i in m.I for j in m.J)
        return opening + transport

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each store's demand must be met
    def demand_rule(m, j):
        return sum(m.ship[i, j] for i in m.I) >= d["demand"][j]

    model.demand_satisfied = pyo.Constraint(model.J, rule=demand_rule)

    # Capacity: cannot ship more than capacity, and only if center is open
    def capacity_rule(m, i):
        return sum(m.ship[i, j] for j in m.J) <= d["capacity"][i] * m.open[i]

    model.capacity_link = pyo.Constraint(model.I, rule=capacity_rule)

    return model
